function cdCurve(m,i,mean){
  let seed=(m.id+'#'+i).split('').reduce((a,c)=>a*31+c.charCodeAt(0)>>>0,7)%233280;
  const rnd=()=>{seed=(seed*9301+49297)%233280; return seed/233280;};
  const ph=rnd()*6, f1=.6+rnd()*.5, f2=1.4+rnd()*.8, tilt=(rnd()-.5)*1.2;
  const raw=Array.from({length:24},(_,k)=>Math.sin(k*f1/3+ph)*.6+Math.sin(k*f2/3+ph*2)*.3+tilt*(k/23-.5));
  const avg=raw.reduce((a,x)=>a+x,0)/raw.length;
  return raw.map(x=>mean+(x-avg)*m.sd*.9);
}
