/* mobile lines 2749-2761 */
function series(m){
  let seed=m.id.split('').reduce((a,c)=>a+c.charCodeAt(0),0);
  const rnd=()=>{seed=(seed*9301+49297)%233280; return seed/233280;};
  const n=m.onePhase?15:44;
  const out=[]; for(let i=0;i<n;i++){
    const p=['Approach','Recovery','Combination','Turns'][Math.floor(rnd()*4)];
    const shift=p==='Approach'?.6:p==='Combination'?-.7:p==='Turns'?-.3:.1;
    /* each stride is ridden on a lead; a slight side bias makes left and right readable */
    const side=rnd()<.5?'L':'R', bias=side==='L'?.18:-.18;
    const centre=m.lr?(side==='L'?m.lr[0]:m.lr[1]):m.base+((m.onePhase?0:shift)+bias)*m.sd;
    out.push({p:m.onePhase?'All strides':p, side, v:centre+((m.lr?shift*.3:0)+(rnd()-.5)*1.6)*m.sd});
  } return out;
}
