function history(key,id,state){ let s=[...(key+id)].reduce((a,c)=>(a*31+c.charCodeAt(0))%233280,11); const r=()=>{s=(s*9301+49297)%233280;return s/233280;};
    const h=[]; for(let i=0;i<5;i++){ const x=r(); h.push(i===4?state:(state==='attention'?(x<.45?'attention':x<.8?'watch':'normal'):state==='watch'?(x<.4?'watch':'normal'):(x<.12?'watch':'normal'))); } return h; }
